const CLASS_DEFS_MUTABLE = Object.fromEntries(
  Object.entries(CLASSIC_ORBS).map(([id, def]) => [id, Object.freeze({
    ...def,
    cooldown: 0,
    progression: combatProgression("damage", 0, 0),
  })]),
);
for (const [id, def] of Object.entries({ ...WEAPON_CLASS_DEFS, ...LEGACY_CLASS_DEFS })) {
  if (id in CLASS_DEFS_MUTABLE) continue;
  Object.defineProperty(CLASS_DEFS_MUTABLE, id, {
    value: Object.freeze(def),
    enumerable: false,
    configurable: false,
    writable: false,
  });
}

export const CLASS_DEFS = Object.freeze(CLASS_DEFS_MUTABLE);
export const CLASS_ROSTER = CLASSIC_ORB_IDS;

export function mechanicTypeFor(type) {
  return CLASS_DEFS[type]?.mechanicType || type;
}

