const RACE_TOP_BOUNDARY = ORB_RACE_PRESENTATION.orbChamberFraction;
const RACE_LAYER_SPAN = ORB_RACE_PRESENTATION.layerStackFraction;
const RACE_FINISH_HEIGHT = ORB_RACE_PRESENTATION.finishFraction;
// Every number-wall lane uses the original portrait race's spacing. Longer
// races extend the same physical course downward; they never squeeze more
// walls into the portrait board's normalized 0..1 height.
export const RACE_LAYER_HEIGHT = RACE_LAYER_SPAN / ORB_RACE_LAYER_COUNT;
export function raceLayerLineY(layerIndex) {
  return RACE_TOP_BOUNDARY + Math.max(0, Number(layerIndex) || 0) * RACE_LAYER_HEIGHT;
}
function raceLayerLineYFor(racer, layerIndex) {
  const index = Math.max(0, Math.floor(Number(layerIndex) || 0));
  const offsets = racer?.raceGravitatorLayerPullOffsets;
  const offset = Array.isArray(offsets) ? Number(offsets[index]) || 0 : 0;
  return raceLayerLineY(index) + offset;
}
export function raceTiltedLayerSurfaceY(layerIndex, x) {
  const safeX = clamp(Number(x) || 0.5, 0, 1);
  const centerDepth = Math.tan(RACE_TILTED_LAYER_ANGLE) * 0.5;
  return raceLayerLineY(layerIndex) + centerDepth * (1 - Math.abs(safeX * 2 - 1));
}

/**
 * Return the upward unit normal for the top edge of the contacted tilted
 * piece. The renderer's two polygons use the same left-down/right-up V, so
 * this is the authoritative physical slope rather than a cosmetic hint.
 */
export function raceTiltedLayerSurfaceNormal(x) {
  const pieceIndex = raceTiltedLayerPieceIndexForX(x);
  const slope = pieceIndex === 0
    ? Math.tan(RACE_TILTED_LAYER_ANGLE)
    : -Math.tan(RACE_TILTED_LAYER_ANGLE);
  const length = Math.hypot(slope, 1) || 1;
  return {
    x: slope / length,
    y: -1 / length,
    slope,
    pieceIndex,
  };
}

function raceTiltedLayerContactY(layerIndex, x, radius) {
  const normal = raceTiltedLayerSurfaceNormal(x);
  return raceTiltedLayerSurfaceY(layerIndex, x) + normal.y * Math.max(0, Number(radius) || 0);
}

function raceTiltedLayerCleared(pieces) {
  return Array.isArray(pieces)
    && pieces.length >= 2
    && pieces.every((pieceHealth) => Math.max(0, Number(pieceHealth) || 0) <= 0);
}

function raceTiltedLayerPiecesFor(sim, racer, layerIndex) {
  if (
    sim?.raceTiltedLayerEnabled !== true
  ) return null;
  const pieces = racer?.raceTiltedLayerHealth?.[layerIndex];
  return Array.isArray(pieces) && pieces.length >= 2 ? pieces : null;
}

function raceTiltedLayerPieceIndexForX(x) {
  const safeX = clamp(Number.isFinite(Number(x)) ? Number(x) : 0.5, 0, 1);
  return safeX < 0.5 ? 0 : 1;
}

function syncRaceTiltedLayerAggregateHealth(racer, layerIndex, pieces) {
  if (!pieces || !Array.isArray(racer?.raceLayerHealth) || layerIndex >= racer.raceLayerHealth.length) return;
  const remaining = pieces.reduce((total, piece) => total + Math.max(0, Number(piece) || 0), 0);
  racer.raceLayerHealth[layerIndex] = remaining / pieces.length;
}

export function raceFinishLineY(layerCount) {
  return raceLayerLineY(Math.max(1, Number(layerCount) || ORB_RACE_LAYER_COUNT));
}
export function raceCheckerStartY(layerCount) {
  return raceFinishLineY(layerCount)
    + RACE_FINISH_HEIGHT * ORB_RACE_PRESENTATION.finishLabelFraction;
}
