// public level ramp explicit. One bounce removes one hundredth of a level.
export const RACE_LASER_DAMAGE_INTERVAL_STEP_SECONDS = RACE_LASER_INTERVAL_LEVEL_STEP;
export const RACE_LASER_MIN_DAMAGE_INTERVAL_SECONDS = 0.00000001;

export function raceLaserIntervalForLevel(level = 1) {
  const safeLevel = Math.max(1, Math.floor(Number(level) || 1));
  return Math.max(
    RACE_LASER_MIN_DAMAGE_INTERVAL_SECONDS,
    RACE_LASER_INITIAL_DAMAGE_INTERVAL_SECONDS
      - (safeLevel - 1) * RACE_LASER_INTERVAL_LEVEL_STEP,
  );
}

export function raceLaserIntervalLevelFor(racer = {}) {
  const storedLevel = Number(racer?.raceLaserIntervalLevel);
  if (Number.isFinite(storedLevel) && storedLevel >= 1) return Math.max(1, Math.floor(storedLevel));
  const legacyInterval = Number(racer?.raceLaserDamageInterval);
  if (Number.isFinite(legacyInterval) && legacyInterval > 0) {
    return Math.max(
      1,
      Math.floor(
        (RACE_LASER_INITIAL_DAMAGE_INTERVAL_SECONDS - legacyInterval)
          / RACE_LASER_INTERVAL_LEVEL_STEP
          + 0.5,
      ) + 1,
    );
  }
  return 1;
}

function raceLaserDamageIntervalFor(racer = {}) {
  const storedLevel = Number(racer?.raceLaserIntervalLevel);
  if (Number.isFinite(storedLevel) && storedLevel >= 1) return raceLaserIntervalForLevel(storedLevel);
  const legacyInterval = Number(racer?.raceLaserDamageInterval);
  return Number.isFinite(legacyInterval) && legacyInterval > 0
    ? Math.max(RACE_LASER_MIN_DAMAGE_INTERVAL_SECONDS, legacyInterval)
    : RACE_LASER_INITIAL_DAMAGE_INTERVAL_SECONDS;
}

export function raceLaserImpactRingCount(interval = RACE_LASER_INITIAL_DAMAGE_INTERVAL_SECONDS) {
    const level = Math.max(
        RACE_LASER_MIN_DAMAGE_INTERVAL_SECONDS,
        Math.min(
          RACE_LASER_INITIAL_DAMAGE_INTERVAL_SECONDS,
          Number(interval) || RACE_LASER_INITIAL_DAMAGE_INTERVAL_SECONDS,
        ),
    );
  return Math.max(
    2,
    Math.min(8, 2 + Math.floor((RACE_LASER_INITIAL_DAMAGE_INTERVAL_SECONDS - level + 1e-9) / RACE_LASER_INTERVAL_LEVEL_STEP)),
  );
}
