// The first Sylvester values are 2, 3, 7, 43, ... . Keep the public helper
// finite so a long recording cannot overflow the shared damage ceiling.
export function sylvesterRaceValue(index) {
  const safeIndex = Math.max(0, Math.floor(Number(index) || 0));
  let value = 2;
  for (let step = 0; step < Math.min(24, safeIndex); step += 1) {
    value = Math.min(ORB_RACE_MAX_MATH_DAMAGE, value * (value - 1) + 1);
  }
  return value;
}

// Lucas numbers begin 2, 1, 3, 4, 7, 11... . Orb Race uses the bounce
// number as n, so the first number-line contact is L1 = 1 and the sequence
// remains deterministic and bounded by the shared math damage ceiling.
export function lucasRaceValue(index) {
  const safeIndex = Math.max(0, Math.floor(Number(index) || 0));
  if (safeIndex === 0) return 2;
  let previous = 2;
  let current = 1;
  for (let step = 1; step < Math.min(104, safeIndex); step += 1) {
    [previous, current] = [current, Math.min(ORB_RACE_MAX_MATH_DAMAGE, previous + current)];
  }
  return Math.min(ORB_RACE_MAX_MATH_DAMAGE, current);
}

// Tetration is represented by the conventional base-two ladder for a^^b:
// 2^^1 = 2, 2^^2 = 4, 2^^3 = 16, 2^^4 = 65536.
export function tetrationRaceValue(height) {
  const safeHeight = Math.max(1, Math.floor(Number(height) || 1));
  let value = 1;
  for (let step = 0; step < Math.min(8, safeHeight); step += 1) {
    value = Math.min(ORB_RACE_MAX_MATH_DAMAGE, 2 ** Math.min(60, value));
  }
  return value;
}

// Square Root follows the mathematical remainder above two health, but its
// displayed-two-health tail needs a finite landing rule. Without this
// separate low-health helper, sqrt(3) leaves 1.732... health and approaches
// one forever instead of clearing the layer.
export function squareRootDamageForLayerHealth(currentLayerHealth) {
  const health = Math.max(0, Number(currentLayerHealth) || 0);
  if (health <= 1) return health;
  if (health <= RACE_SQUARE_ROOT_TWO_HEALTH_THRESHOLD + 1e-9) {
    return RACE_SQUARE_ROOT_TWO_HEALTH_DAMAGE;
  }
  return Math.max(0, health - Math.sqrt(health));
}
