            fighterId: owner.id,
            targetId: ray.target.id,
            entityId: entity.id,
            rayIndex: entity.rayIndex,
            amount: dealt,
            damageAmount: dealt,
            healAmount: 0,
            health: ray.target.health,
            targetHealth: ray.target.health,
